INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63782931', 63782931, 'analyze_legacy', 'Provinsi Sulawesi Selatan', 'provinsi', 'DINAS PEMBERDAYAAN PEREMPUAN, PERLINDUNGAN ANAK, PENGENDALIAN PENDUDUK, DAN KELUARGA BERENCANA', 'Belanja Alat/Bahan untuk Kegiatan Kantor-Alat Tulis Kantor', 'Barang', 'E-Purchasing', 'Sulawesi Selatan, Makassar (Kota)', 5366550, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Spanduk; Baliho Hari Besar / Ucapan; Fotokopi;', 'Ukuran 1x3 Meter; Bahan Vinyl, Ukuran 2x3 Meter; Hitam Putih, A4;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1144451);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63823756', 63823756, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Pusat Pasar Kerja', 'Jasa Penyelenggaran Acara Pengadaan Job Fair Nasional Pusat Pasar Kerja Tahun 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 10005000000, 'August 2026', 'APBN - PNBP (D)', 0, 1, '3 Paket', 'Pameran kesempatan kerja atau job fair merupakan acara yang mempertemukan pencari kerja dengan perusahaan yang sedang membuka lowongan. Acara ini diselenggarakan dengan tujuan utama untuk memfasilitasi proses rekrutmen dan memberikan informasi mengenai dunia kerja. Salah satu contoh keberhasilannya dapat dilihat dalam "Job Fair Tahun 2024," di mana 100 perusahaan menawarkan lebih dari 10.000 lowongan pekerjaan, menarik ribuan pencari kerja dari berbagai daerah. Selain mempercepat proses rekrutmen, pameran kesempatan kerja juga bertujuan untuk mengurangi tingkat pengangguran dengan menjembatani kebutuhan tenaga kerja dan industri. Pemerintah dan berbagai lembaga pendidikan sering terlibat dalam penyelenggaraan acara ini untuk membantu lulusan baru memperoleh pekerjaan dan membangun jaringan profesional. Sebagai contoh, Festival Pelatihan Vokasi dan Job Fair Nasional 2024 yang diselenggarakan oleh Kementerian Ketenagakerjaan berhasil menarik minat masyarakat untuk meningkatkan keterampilan mereka guna bersaing di pasar kerja. Alasan lain penyelenggaraan pameran kerja adalah untuk memberikan wawasan kepada pencari kerja mengenai tren industri dan keterampilan yang dibutuhkan di masa depan. Acara ini sering kali mencakup seminar dan workshop yang menghadirkan para pakar industri, memungkinkan peserta memperoleh pemahaman lebih mendalam tentang bidang pekerjaan yang diminati. Selain itu, pameran kerja juga menjadi kesempatan bagi perusahaan untuk membangun citra positif di mata masyarakat dan menarik lebih banyak talenta berkualitas. Dengan berbagai manfaat yang ditawarkan, pameran kesempatan kerja menjadi salah satu strategi efektif dalam meningkatkan kualitas tenaga kerja dan menyeimbangkan kebutuhan antara pencari kerja dan perusahaan. Oleh karena itu, acara seperti ini terus dikembangkan untuk memberikan peluang yang lebih luas bagi seluruh pihak yang terlibat.', 'Pengadaan Job Fair Nasional ( 3, PKT, @ 3335000000 );  Penyelenggaran Pameran Kesempatan Kerja Tahun 2026 dilaksanakan di Jakarta  Kegiatan Pameran Kesempatan Kerja Tahun 2025 dilaksanakan selama 2 hari dengan proses persiapan lokasi acara yang mencakup konstruksi, dekorasi serta persiapan sarana dan prasarana kegiatan dimulai sejak H-2 penyelenggaraan Pameran Kesempatan Kerja Tahun 2026.  Prasarana yang perlu dibangun di lokasi penyelenggaraan acara mencakup: o Booth untuk perusahaan pemberi kerja pada acara job fair; o 1 buah booth berukuran custom untuk Pusat Pasar Kerja (contoh booth custom); o Signage dekorasi event dengan materi fascia flexy; o LED Videotron; o Gate masuk venue; o Gambar (layout) pelaksanaan acara pameran kesempatan kerja.  Persiapan • Melakukan identifikasi lokasi kegiatan; • Melakukan rapat-rapat internal teknis dalam rangka penentuan kebutuhan dalam pelaksanaan kegiatan dengan mengundang narasumber yang ahli di bidang perencanaan event/ kegiatan; • Melakukan perbandingan harga melalui e-katalog berdasarkan RAB yang telah disusun oleh Narasumber Perencanaan Event ; • Penandatanganan kontrak dan koordinasi teknis dengan Tim penyedia. • Inventarisasi kebutuhan pelaksanaan kegiatan baik secara administrasi maupun teknis; • Menyusun agenda pelaksanaan kegiatan termasuk pembuatan SK dan bantuan personil yang akan dilibatkan dalam pelaksanaan kegiatan; • Mengajukan perijinan pelaksanaan Job Fair ke Ditjen Binapenta dan PKK. • Melakukan promosi ke masyarakat.  Pelaksanaan • Pameran Kesempatan Kerja/ Job Fair Tahun 2026 akan dilaksanakan selama 2 (dua) hari; • Mencakup pemberian layanan kepada pencari kerja dan pemberi kerja, sosialiasi layanan dan program di masing-masing unit di Kementerian Ketenagakerjaan, layanan secara langsung, talkshow interaktif, dan acara hiburan.  Pelaporan dan Evaluasi Pelaporan dan evaluasi dilakukan setelah penyelenggaraan kegiatan Pameran Kesempatan Kerja Tahun 2025. Penyelenggaraan Pameran Kesempatan Kerja Tahun 2025 akan diserahkan kepada Penyelenggara Acara (EO) yang sudah memiliki pengalaman menyelenggarakan beragam kegiatan Kementerian Ketenagakerjaan bertaraf nasional. Pengadaan dan penetapan Event Organizer (EO) dilaksanakan melalui mekanisme belanja E-Katalog sesuai dengan prosedur yang berlaku. Tugas dan tanggung jawab EO antara lain sebagai berikut: 1) Perencanaan kegiatan: a) Mengevaluasi opsi lokasi penyelenggaraan. b) Menyusun rancangan kegiatan, kepanitian, serta keterlibatan masing-masing unit. c) Menyusun rancangan desain: Visual Utama (Key Visual) serta turunan yang mencakup : backdrop, materi publikasi cetak dan digital, konten LED, dll. Rancang bangun dan tata letak lokasi acara yang mencakup : layout venue, desain booth, desain panggung, desain dekorasi tambahan. d) Menyusun skema kerja dan skema jadwal persiapan, pelaksanaan hingga pasca event secara detail. 2) Persiapan dan pelaksanaan kegiatan: a) Melaksanakan konsep acara sesuai dengan agenda yang telah disusun; b) Penyelenggara Pameran Kesempatan Kerja menyediakan: • Setting venue, pelaksanaan acara; • Spanduk, dekorasi venue acara dan sektor pendukung lainnya; • EO Bertangung jawab atas berfungsinya semua peralatan teknis dengan optimal, termasuk sound system, band gear dan lighting selama acara; • EO bertangung jawab atas pengisi acara, MC, narasumber, personil konstruksi, proses loading in/out prasarana acara, serta manpower pendukung maupun pengamanan selama kegiatan berlangsung; • EO bertanggung jawab untuk mendokumentasikan seluruh rangkaian kegiatan mulai dari pra-pelaksanaan hingga paska kegiatan; • EO wajib mengkomunikasikan segala hal yang terkait dengan kegiatan penyelenggaraan ini. Jika ada perubahan mendasar mengenai segala hal yang terkait dengan pekerjaan ini, EO wajib mengajukan approval/persetujuan terlebih dahulu dengan panitia penyelenggara (EO tidak diperkenankan memutuskan secara sepihak); • EO bertanggung jawab untuk memenuhi seluruh permintaan dan semua kebutuhan panitia terkait kegiatan ini yang sifatnya tak terduga dan urgent saat pelaksanaan kegiatan; • EO wajib membuat laporan penyelenggaran dan pertanggungjawaban secara terperinci mengenai seluruh rangkaian kegiatan per jenis kegiatan, baik sebelum pelaksanaan, pada saat pelaksanaan, dan setelah pelaksanaan. Laporan terdiri atas : - Laporan kegiatan disertai keterangan setiap item yang tercantum dalam E-katalog, - Rekap dokumentasi foto pra hingga pasca pelaksanaan kegiatan yang dapat dikompilasi dalam wujud perangkat keras atau lunak. • Rincian segala hal yang menyangkut kegiatan ini, disampaikan secara terpisah dalam Rencana Anggaran Biaya (RAB). 3) Persyaratan Penyedia Jasa Penyelenggara Acara yang dinilai dan ditetapkan oleh UKPBJ Kementerian Ketenagakerjaan harus memenuhi persyaratan yang diwajibkan sebagaimana tertuang pada Peraturan Presiden Nomor 12 Tahun 2021 Tentang Perubahan Atas PERPRES Nomor 16 Tahun 2018 Tentang Pengadaan Barang/Jasa Pemerintah. Disamping itu, untuk menjamin kualitas penyelenggaraan Naker Fest 2024, PCO yang ditetapkan harus memenuhi kualifikasi berikut ini, yaitu: a) Kualifikasi Perusahaan 1. Penyedia jasa memiliki klasifikasi KBLI 82301 yaitu MICE (Meeting, Incentive Conference, and Exhibition) 2. Wajib memiliki pengalaman menyelenggarakan kegiatan event Job Fair, sekurang-kurangnya diikuti oleh 45 Perusahaan atau event lainnya yang setara. 3. Melampirkan sertifikat ISO 9001 :2015 Provision of General Meetings; Incentives; Conference & Exhibitions (MICE) yang masih berlaku; 4. Melampirkan bukti anggota KADIN dan Asosiasi Bidang MICE - ASPERAPI dengan melampirkan sertifikat yang masih berlaku; 5. Melampirkan Sertifikat Badan Usaha (SBU) kompetensi bidang MICE dari KADIN; b) Spesifikasi Teknis Pelaksanaan Job Fair Spesifikasi teknis yang diperlukan, meliputi: • Hasil yang dapat diproduksi/diselesaikan, termasuk design, harus memenuhi standar mutu/kualitas yang ditetapkan dan memiliki pengalaman penyelenggaraan kegiatan berskala nasional; • Memastikan acara berjalan dengan lancar serta melaksanakan konsep acara sesuai agenda yang telah disusun dan menyediakan pendukug acara dengan rincian: • MC dan Moderator yang memiliki kemampuan artikulasi dan elaborasi yang baik dan lancar, berpengalaman.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1144452);
