INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63764516', 63764516, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Pembuatan Monitoring dan Analisis Media Sosial', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 170000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Pekerjaan **Pembuatan Monitoring dan Analisis Media Sosial** merupakan kegiatan strategis Biro Hubungan Masyarakat Kementerian Ketenagakerjaan yang dilaksanakan secara berkelanjutan sepanjang tahun 2026 untuk mendukung pengelolaan komunikasi publik yang terukur, responsif, dan berbasis data. Uraian pekerjaan ini meliputi pemantauan harian terhadap percakapan, pemberitaan, dan interaksi publik di berbagai platform media sosial serta media digital terkait kebijakan, program, dan isu ketenagakerjaan; pengumpulan dan pengolahan data kinerja akun resmi; analisis sentimen, tren isu, jangkauan, dan keterlibatan audiens; penyusunan laporan analisis berkala dan insidentil sebagai bahan evaluasi dan rekomendasi strategi komunikasi; serta penyediaan peringatan dini (early warning) terhadap potensi isu krusial yang berdampak pada citra dan kepercayaan publik terhadap Kementerian Ketenagakerjaan.', 'Penyedia melakukan pemantauan rutin percakapan, pemberitaan, dan interaksi publik terkait program, kebijakan, layanan, serta isu strategis Kementerian Ketenagakerjaan pada platform media sosial/kanal digital yang relevan; mencakup pengumpulan dan pengolahan data kinerja akun resmi (jangkauan, impresi, keterlibatan, pertumbuhan audiens, dan indikator lain yang tersedia), analisis tren isu serta sentimen (positif/negatif/netral) berikut pemetaan aktor/kanal penyebaran, penyampaian peringatan dini atas isu berpotensi krisis, serta penyusunan laporan monitoring dan analisis secara berkala (harian/mingguan/bulanan) dan insidentil disertai rekomendasi tindak lanjut komunikasi yang dapat dieksekusi, lengkap dengan dokumentasi sumber/tautan temuan sebagai bahan evaluasi dan pengambilan keputusan pimpinan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1148407);
